async function sreq(method,key,query,body,extra){
  var t=new Date(),amz=t.toISOString().replace(/[:-]/g,'').split('.')[0]+'Z',date=amz.substring(0,8);
  var scope=date+'/'+R+'/s3/aws4_request';
  var path='/'+B+'/'+(key?key.split('/').map(E).join('/'):'');
  var qs=Object.keys(query||{}).sort().map(function(k){return E(k)+'='+E(query[k])}).join('&');
  var ph=body?await SH(body):'UNSIGNED-PAYLOAD';
  var hd={host:H,'x-amz-content-sha256':ph,'x-amz-date':amz};
  var sh=Object.keys(hd).sort().join(';');
  var ch=Object.keys(hd).sort().map(function(k){return k+':'+hd[k]+'\n'}).join('');
  var cr=method+'\n'+path+'\n'+qs+'\n'+ch+'\n'+sh+'\n'+ph;
  var s2s='AWS4-HMAC-SHA256\n'+amz+'\n'+scope+'\n'+await SH(cr);
  var kD=await HM('AWS4'+SK,date),kS=await HM(await HM(await HM(kD,R),'s3'),'aws4_request');
  var sig=HX(await HM(kS,s2s));
  var hh=Object.assign({},hd,extra||{});
  hh.Authorization='AWS4-HMAC-SHA256 Credential='+AK+'/'+scope+', SignedHeaders='+sh+', Signature='+sig;
  return fetch('https://'+H+path+(qs?'?'+qs:''),{method:method,body:body,headers:hh});
}

async function presign(key,mins){
  var t=new Date(),amz=t.toISOString().replace(/[:-]/g,'').split('.')[0]+'Z',date=amz.substring(0,8);
  var scope=date+'/'+R+'/s3/aws4_request';
  var path='/'+B+'/'+key.split('/').map(E).join('/');
  var mime=mimeOf(key);
  var qs=['X-Amz-Algorithm=AWS4-HMAC-SHA256','X-Amz-Credential='+E(AK+'/'+scope),'X-Amz-Date='+amz,
    'X-Amz-Expires='+((mins||10080)*60),'X-Amz-SignedHeaders=host','response-content-disposition=inline',
    'response-content-type='+E(mime)].sort().join('&');
  var s2s='AWS4-HMAC-SHA256\n'+amz+'\n'+scope+'\n'+await SH('GET\n'+path+'\n'+qs+'\nhost:'+H+'\n\nhost\nUNSIGNED-PAYLOAD');
  var kD=await HM('AWS4'+SK,date),kS=await HM(await HM(await HM(kD,R),'s3'),'aws4_request');
  return 'https://'+H+path+'?'+qs+'&X-Amz-Signature='+HX(await HM(kS,s2s));
}

async function put(key,file,onProgress){
  var buf=await file.arrayBuffer();
  var ct=file.type||mimeOf(file.name);
  if(onProgress)onProgress(15);
  var res=await sreq('PUT',key,{},buf,{'Content-Type':ct});
  if(onProgress)onProgress(100);
  if(!res||!res.ok)throw new Error('Upload failed ('+(res?res.status:'no response')+')');
  return {key:key,url:await presign(key),size:file.size,type:ct};
}

async function del(key){return sreq('DELETE',key,{},null,{})}

async function getText(key){
  var u=await presign(key,60);
  var r=await fetch(u);
  if(!r.ok)throw new Error('Could not read that file.');
  return r.text();
}

window.__nx_tp={put:put,del:del,presign:presign,getText:getText,mimeOf:mimeOf};
